import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int[] cumSums = new int[51];
        cumSums[0] = 1;
        for (int i = 1; i < 51; i++) {
            cumSums[i] = cumSums[i - 1] + (1 << i);
        }

        int h = sc.nextInt();
        int n = sc.nextInt();

        n = n + cumSums[h - 1];
        int[] sequence = new int[1000]; // Arbitrary size, should be enough
        int seqIndex = 0;
        sequence[seqIndex++] = n;

        while (n != 1) {
            n /= 2;
            sequence[seqIndex++] = n;
        }

        int totalMoves = 0;
        int current = 1;
        boolean flipBit = false;

        while (current != sequence[0]) {
            int[] tempSeq = new int[51];
            int tempSeqIdx = 0;
            int tempNode = current;
            boolean tempFlipBit = flipBit;

            for (int i = 0; i < h; i++) {
                tempSeq[tempSeqIdx++] = tempNode;
                if (!tempFlipBit) {
                    tempNode *= 2;
                } else {
                    tempNode = tempNode * 2 + 1;
                }
                tempFlipBit = !tempFlipBit;
            }

            if (tempNode == sequence[0]) {
                totalMoves += h;
                break;
            }

            // Append tempNode to tempSeq
            int[] fullTempSeq = new int[tempSeqIdx + 1];
            System.arraycopy(tempSeq, 0, fullTempSeq, 0, tempSeqIdx);
            fullTempSeq[tempSeqIdx] = tempNode;

            // Reverse fullTempSeq
            for (int i = 0; i < fullTempSeq.length / 2; i++) {
                int tmp = fullTempSeq[i];
                fullTempSeq[i] = fullTempSeq[fullTempSeq.length - 1 - i];
                fullTempSeq[fullTempSeq.length - 1 - i] = tmp;
            }

            boolean found = false;
            for (int i = 1; i <= h; i++) {
                if (sequence[i] == fullTempSeq[i]) {
                    totalMoves += cumSums[i - 1] + h - i + 1;
                    h = i - 1;
                    current = fullTempSeq[i - 1];
                    if (current == fullTempSeq[i] * 2) {
                        current = fullTempSeq[i] * 2 + 1;
                        flipBit = false;
                    } else {
                        current = fullTempSeq[i] * 2;
                        flipBit = true;
                    }
                    found = true;
                    break;
                }
            }
            if (!found) {
                // If no match found, break to prevent infinite loop
                break;
            }
        }
        System.out.println(totalMoves);
        sc.close();
    }
}
